def magic_square_test(matrix):
    n = len(matrix)
    if n != len(matrix[0]):
        return False

    # Calculate the sum of the first row to use as the target sum for each row, column, and diagonal.
    target_sum = sum(matrix[0])

    # Check rows and columns
    for i in range(n):
        if sum(matrix[i]) != target_sum or sum(matrix[j][i] for j in range(n)) != target_sum:
            return False

    # Check diagonals
